46	  using fw_if = tlm::tlm_fw_transport_if<protocol_types>;
47	  std::vector<std::tuple<MemoryRegion, fw_if*, std::string>> memory_regions;
48	  std::vector<std::tuple<MemoryRegion, std::string>> reserved_regions;
49	  std::set<fw_if*> bound_targets;
