51	  auto find_fw_if_from_address(const uint64_t addr) -> fw_if*
52	  {
53	    for (const auto& [mr, socket, _]: this->memory_regions) {
54	      if (mr.contains(addr))
55	        return socket;
56	    }
57	
58	    return nullptr;
59	  }
