61	  auto nb_transport_fw(const int id,
62	                       tlm::tlm_generic_payload& trans,
63	                       tlm::tlm_phase& phase,
64	                       sc_core::sc_time& delay) -> tlm::tlm_sync_enum
65	  {
66	    const auto addr = trans.get_address();
67	    assert(id >= 0 && unsigned(id) < this->target_sockets.size());
68	    const auto target = this->find_fw_if_from_address(addr);
69	    if (!target) {
70	      spdlog::critical("target socket not found for address {:#x}, "
71	                       "initiator_port={}, cmd={}, len={}",
72	                       addr, id, trans.is_read() ? "read" : "write",
73	                       trans.get_data_length());
74	      trans.set_response_status(tlm::TLM_ADDRESS_ERROR_RESPONSE);
75	      return tlm::tlm_sync_enum::TLM_COMPLETED;
76	    }
77	
78	    const auto sync = target->nb_transport_fw(trans, phase, delay);
79	    if (sync != tlm::TLM_COMPLETED) {
80	      this->trans_map[&trans] = id;
81	    }
82	    return sync;
83	  }
